/* Virtual try-on.
 *
 * APPROACH (how the frame ends up looking natural)
 * 1. The user's photo is drawn onto a <canvas> (downscaled to <= 1600px, EXIF orientation applied by the browser).
 * 2. MediaPipe Face Landmarker (vendored in /static/vendor/mediapipe, runs 100% in the browser via WASM - the
 *    photo is never uploaded) returns 478 landmarks. Landmarks 468 and 473 are the two iris centres = the pupils.
 * 3. Each frame overlay is an SVG generated by the Python back end in REAL MILLIMETRES (see frames_svg.py), with
 *    the point between the pupils at the exact centre of the SVG. So:
 *        pixels-per-mm  = pupil distance in the photo / 63 mm   (average adult pupillary distance)
 *        overlay width  = svg width in mm * pixels-per-mm        -> Small/Large frames really differ in size
 *        overlay centre = midpoint of the pupils
 *        overlay rotate = angle of the line between the pupils   -> follows head roll/tilt
 * 4. If the model cannot load or no face is found (side profile, sunglasses, very small face...), we fall back to a
 *    sensible default placement and the user positions the frame by hand: drag, scroll/slider to resize, slider to tilt,
 *    arrow keys to nudge. Manual fine-tuning is always available, even after a successful auto-fit.
 *
 * Known limit: it's a 2-D overlay, so strong head turns (yaw) can't be matched - front-facing photos work best.
 */
import { $, $$, el, getJSON, money, reducedMotion } from './api.js';

const AVG_PD_MM = 63;
const MAX_SIDE = 1600;
const DEFAULT_PD_FRAC = 0.27; // fallback: pupil distance as a fraction of photo width

let frames = [];
let current = null;
let landmarker = null;                // lazily created on first photo
let photo = null;                     // { w, h }
// placement, all as fractions of the photo so it survives resizing
const face = { cx: .5, cy: .42, pd: DEFAULT_PD_FRAC, rot: 0, found: false };
const user = { dx: 0, dy: 0, scale: 1, rot: 0 };

const stage = () => $('#stage');
const overlay = () => $('#frameImg');

export async function initTryOn({ onShopFrame } = {}) {
  frames = await getJSON('/api/products?category=frames');
  const picker = $('#picker');
  picker.replaceChildren(...frames.map((f) => el('button', { class: 'pick', role: 'option', 'aria-selected': 'false', 'data-id': f.id, title: f.name, onclick: () => selectFrame(f.id) },
    el('img', { src: f.tryon.overlay, alt: '', loading: 'lazy', width: 120, height: 40 }), el('span', {}, f.name))));
  selectFrame(frames[0].id, { quiet: true });

  const file = $('#file'), drop = $('#dropzone');
  const choose = () => file.click();
  drop.addEventListener('click', choose);
  drop.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); choose(); } });
  $('#change').addEventListener('click', choose);
  // reset the value after reading so choosing the very same photo again still triggers `change`
  file.addEventListener('change', () => { const f = file.files[0]; file.value = ''; if (f) loadPhoto(f); });
  for (const ev of ['dragenter', 'dragover']) drop.addEventListener(ev, (e) => { e.preventDefault(); drop.classList.add('drag'); });
  for (const ev of ['dragleave', 'drop']) drop.addEventListener(ev, (e) => { e.preventDefault(); drop.classList.remove('drag'); });
  drop.addEventListener('drop', (e) => e.dataTransfer.files[0] && loadPhoto(e.dataTransfer.files[0]));
  // dropping onto the stage replaces the photo too
  stage().addEventListener('dragover', (e) => e.preventDefault());
  stage().addEventListener('drop', (e) => { e.preventDefault(); e.dataTransfer.files[0] && loadPhoto(e.dataTransfer.files[0]); });

  $('#scale').addEventListener('input', (e) => { user.scale = e.target.value / 100; $('#scaleOut').textContent = `${e.target.value}%`; place(); });
  $('#rot').addEventListener('input', (e) => { user.rot = +e.target.value; $('#rotOut').textContent = `${e.target.value}°`; place(); });
  $('#autofit').addEventListener('click', () => { Object.assign(user, { dx: 0, dy: 0, scale: 1, rot: 0 }); syncSliders(); place(); status(face.found ? 'Re-fitted to your eyes.' : 'No face data - centred as a starting point.'); });
  $('#download').addEventListener('click', download);
  enableDrag();
  $('#tryonShop').append(el('a', { href: '#shop', onclick: () => onShopFrame?.() }, 'Love one? Browse all frames →'));
  return { selectFrame };
}

export function selectFrame(id, { quiet = false, scroll = false } = {}) {
  current = frames.find((f) => f.id === id) || current;
  $$('.pick').forEach((b) => b.setAttribute('aria-selected', +b.dataset.id === current.id));
  const img = overlay();
  img.src = current.tryon.overlay; img.alt = `${current.name} - drag to reposition`;
  const s = current.specs;
  $('#picked').textContent = `${current.name} · ${s.shape}, ${s.material} · ${s.lens_width}-${s.bridge}-${s.temple} mm · ${money(current.price)}`;
  place();
  if (scroll) $('#tryon').scrollIntoView({ behavior: reducedMotion ? 'auto' : 'smooth' });
  if (!quiet && !photo) status('Upload a photo to see it on your face.');
}

function status(msg, fade = true) {
  const s = $('#status'); s.textContent = msg; s.classList.remove('fade');
  clearTimeout(status.t);
  if (msg && fade) status.t = setTimeout(() => s.classList.add('fade'), 5000);
}

async function loadPhoto(file) {
  if (!file.type.startsWith('image/')) { alert('Please choose an image file (JPG, PNG or WebP).'); return; }
  const bmp = await createImageBitmap(file).catch(() => null); // honours EXIF orientation
  if (!bmp) { alert('Sorry, that image could not be read. Try a JPG or PNG.'); return; }
  const k = Math.min(1, MAX_SIDE / Math.max(bmp.width, bmp.height));
  const cv = $('#photo');
  cv.width = Math.round(bmp.width * k); cv.height = Math.round(bmp.height * k);
  cv.getContext('2d').drawImage(bmp, 0, 0, cv.width, cv.height);
  photo = { w: cv.width, h: cv.height };
  stage().style.setProperty('--ar', photo.w / photo.h);
  $('#dropzone').hidden = true; stage().hidden = false;
  ['autofit', 'change', 'download'].forEach((id) => { $('#' + id).disabled = false; });
  Object.assign(user, { dx: 0, dy: 0, scale: 1, rot: 0 }); syncSliders();
  Object.assign(face, { cx: .5, cy: .42, pd: DEFAULT_PD_FRAC, rot: 0, found: false });
  place();
  status('Finding your eyes…', false);
  try {
    const lm = await detect(cv);
    if (lm) { applyLandmarks(lm); status('Frame fitted to your eyes - drag or use the sliders to fine-tune.'); }
    else status('Could not find a face - position the frame by hand (drag, resize, tilt).');
  } catch (err) {
    console.warn('Face model unavailable, manual mode:', err);
    status('Auto-fit is unavailable here - position the frame by hand (drag, resize, tilt).');
  }
  place();
  stage().scrollIntoView({ block: 'nearest', behavior: reducedMotion ? 'auto' : 'smooth' });
}

async function detect(canvas) {
  if (!landmarker) {
    const { FilesetResolver, FaceLandmarker } = await import('/static/vendor/mediapipe/vision_bundle.mjs');
    const fileset = await FilesetResolver.forVisionTasks('/static/vendor/mediapipe/wasm');
    landmarker = await FaceLandmarker.createFromOptions(fileset, {
      baseOptions: { modelAssetPath: '/static/vendor/mediapipe/face_landmarker.task' }, runningMode: 'IMAGE', numFaces: 1,
    });
  }
  return landmarker.detect(canvas).faceLandmarks?.[0] || null;
}

function applyLandmarks(lm) {
  const px = (i) => ({ x: lm[i].x * photo.w, y: lm[i].y * photo.h });
  const mid = (a, b) => ({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 });
  // iris centres (468/473) when present, otherwise the middle of each eye's corners
  let a = lm.length > 473 ? px(468) : mid(px(33), px(133));
  let b = lm.length > 473 ? px(473) : mid(px(362), px(263));
  if (a.x > b.x) [a, b] = [b, a];
  face.cx = (a.x + b.x) / 2 / photo.w; face.cy = (a.y + b.y) / 2 / photo.h;
  face.pd = Math.hypot(b.x - a.x, b.y - a.y) / photo.w;
  face.rot = Math.atan2(b.y - a.y, b.x - a.x) * 180 / Math.PI;
  face.found = true;
}

/** Position the overlay from face + user adjustments. */
function place() {
  const img = overlay();
  if (!current || !photo) { img.hidden = true; return; }
  img.hidden = false;
  const widthFrac = current.tryon.width_mm * (face.pd / AVG_PD_MM) * user.scale;
  img.style.width = `${widthFrac * 100}%`;
  img.style.left = `${(face.cx + user.dx) * 100}%`;
  img.style.top = `${(face.cy + user.dy) * 100}%`;
  img.style.setProperty('--rot', `${face.rot + user.rot}deg`);
}

function syncSliders() {
  $('#scale').value = Math.round(user.scale * 100); $('#scaleOut').textContent = `${Math.round(user.scale * 100)}%`;
  $('#rot').value = user.rot; $('#rotOut').textContent = `${Math.round(user.rot)}°`;
}

function enableDrag() {
  const img = overlay(), box = stage();
  let drag = null;
  img.addEventListener('pointerdown', (e) => { img.setPointerCapture(e.pointerId); drag = { x: e.clientX, y: e.clientY, dx: user.dx, dy: user.dy }; e.preventDefault(); });
  img.addEventListener('pointermove', (e) => {
    if (!drag) return;
    const r = box.getBoundingClientRect();
    user.dx = drag.dx + (e.clientX - drag.x) / r.width;
    user.dy = drag.dy + (e.clientY - drag.y) / r.height;
    place();
  });
  const end = () => { drag = null; };
  img.addEventListener('pointerup', end); img.addEventListener('pointercancel', end);
  img.addEventListener('wheel', (e) => { // scroll while hovering the frame to resize; page scroll is untouched everywhere else
    e.preventDefault();
    user.scale = Math.min(1.6, Math.max(.6, user.scale * (e.deltaY < 0 ? 1.04 : .96))); syncSliders(); place();
  }, { passive: false });
  img.addEventListener('keydown', (e) => {
    const step = e.shiftKey ? .02 : .005, k = e.key;
    if (k === 'ArrowLeft') user.dx -= step; else if (k === 'ArrowRight') user.dx += step;
    else if (k === 'ArrowUp') user.dy -= step; else if (k === 'ArrowDown') user.dy += step;
    else if (k === '+' || k === '=') user.scale = Math.min(1.6, user.scale * 1.03);
    else if (k === '-') user.scale = Math.max(.6, user.scale / 1.03);
    else if (k === '[') user.rot = Math.max(-25, user.rot - 1); else if (k === ']') user.rot = Math.min(25, user.rot + 1);
    else return;
    e.preventDefault(); syncSliders(); place();
  });
}

async function download() {
  const out = document.createElement('canvas');
  out.width = photo.w; out.height = photo.h;
  const ctx = out.getContext('2d');
  ctx.drawImage($('#photo'), 0, 0);
  const img = new Image();
  img.src = current.tryon.overlay;
  await img.decode();
  const w = current.tryon.width_mm * (face.pd / AVG_PD_MM) * user.scale * photo.w;
  const h = w * img.naturalHeight / img.naturalWidth;
  ctx.translate((face.cx + user.dx) * photo.w, (face.cy + user.dy) * photo.h);
  ctx.rotate((face.rot + user.rot) * Math.PI / 180);
  ctx.shadowColor = 'rgba(0,0,0,.25)'; ctx.shadowBlur = w * .01; ctx.shadowOffsetY = w * .01;
  ctx.drawImage(img, -w / 2, -h / 2, w, h);
  out.toBlob((blob) => {
    const a = el('a', { href: URL.createObjectURL(blob), download: `paul-optical-${current.name.toLowerCase().replace(/\W+/g, '-')}.png` });
    a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 2000);
  }, 'image/png');
}
